#!/usr/bin/env Rscript
#
# Feature Heatmap Clustering Analysis in R
#
# This script reads the top_100_features.txt file generated by binary_classification_feature_importance.py,
# filters the original values of the top 100 most important features, performs ward clustering on samples and features,
# and finally generates a heatmap using pheatmap.

# 设置错误处理选项，显示完整的调用栈信息
options(error = function() traceback(sys.calls(), max.lines = 200))
options(warn = 1) # 实时显示警告信息

# 加载必要的库
library(optparse)
library(pheatmap)
library(ggpubr)
library(dplyr)
library(tidyr)
library(RColorBrewer)
library(tools)  # 用于file_path_sans_ext函数

# 定义命令行参数
option_list <- list(
  make_option(c("--top_features_file"), type="character", default=NULL, 
              help="Path to top_300_features.txt file", metavar="character"),
  make_option(c("--feature_matrix"), type="character", default=NULL, 
              help="Path to feature matrix file (long format tsv, with header)", metavar="character"),
  make_option(c("--all_samples"), type="character", default=NULL, 
              help="Path to all samples ID file (tsv, no header)", metavar="character"),
  make_option(c("--output_prefix"), type="character", default="./feature_heatmap", 
              help="Prefix for output files (will generate output_prefix.png and output_prefix.pdf) [default= %default]", metavar="character"),
  make_option(c("--annotation_file"), type="character", default=NULL, 
              help="Path to sample annotation file (TSV with header)", metavar="character"),
  make_option(c("--feature_rate_annotation_file"), type="character", default=NULL, 
              help="Path to feature rate annotation file (TSV with header, containing HOG and Presence_Rate_Interval columns)", metavar="character"),
  make_option(c("--feature_secreted_annotation_file"), type="character", default=NULL, 
              help="Path to feature secreted annotation file (TSV with no header, two columns: feature ID and secreted status)", metavar="character"),
  make_option(c("--figsize_width"), type="integer", default=20, 
              help="Heatmap width (default: 20)", metavar="integer"),
  make_option(c("--figsize_height"), type="integer", default=20, 
              help="Heatmap height (default: 20)", metavar="integer"),
  make_option(c("--cmap"), type="character", default="RdYlBu",
              help="Color map (default: RdYlBu)", metavar="character"),
  make_option(c("--cellwidth"), type="integer", default=6,
              help="Cell width in mm (default: 6)", metavar="integer"),
  make_option(c("--cellheight"), type="integer", default=6,
              help="Cell height in mm (default: 6)", metavar="integer"),
  make_option(c("--skip_normalization"), action="store_true", default=FALSE,
              help="Skip normalization for count data (plot raw counts)"),
  make_option(c("--keep_all_features"), action="store_true", default=FALSE,
              help="Keep all features including those with identical values across samples")
)

# 解析命令行参数
opt_parser <- OptionParser(option_list=option_list)
opt <- parse_args(opt_parser)

# 检查必需参数
if (is.null(opt$top_features_file) || is.null(opt$feature_matrix) || is.null(opt$all_samples)) {
  print_help(opt_parser)
  stop("Missing required arguments", call.=FALSE)
}

# 确保输出目录存在
output_dir <- dirname(opt$output_prefix)
if (!is.null(output_dir) && output_dir != "" && !dir.exists(output_dir)) {
  dir.create(output_dir, recursive=TRUE)
  cat(paste("Creating output directory:", output_dir, "\n"))
}

# 全局变量存储特征重要性信息
feature_importance_order <<- c()

# 加载top features
load_top_features <- function(top_features_file) {
  cat(paste("Reading top features file:", top_features_file, "\n"))
  # 读取top_features文件
  top_features_df <- read.delim(top_features_file, stringsAsFactors=FALSE, header=TRUE)
  
  # 检查文件列数
  if (ncol(top_features_df) == 1) {
    # 单列表格情况：默认第一列是特征ID
    cat("Detected single column input file, treating as feature subset list\n")
    
    # 获取特征ID列表（使用第一列）
    top_feature_ids <- top_features_df[[1]]
    
    # 去除可能的NA值
    top_feature_ids <- top_feature_ids[!is.na(top_feature_ids) & top_feature_ids != ""]
    
    cat(paste("Successfully loaded", length(top_feature_ids), "features from single column file\n"))
    
    # 保存特征顺序（与输入文件一致）
    feature_importance_order <<- top_feature_ids
    
    return(top_feature_ids)
  } else {
    # 多列表格情况：按照原逻辑处理
    # 检查文件格式是否正确
    required_columns <- c("Feature", "Importance", "P_value", "Bonferroni_p_value")
    missing_columns <- setdiff(required_columns, colnames(top_features_df))
    
    if (length(missing_columns) > 0) {
      stop(paste("File", top_features_file, "format is incorrect, missing columns:", 
                 paste(missing_columns, collapse=", ")))
    }
    
    # 筛选P_value小于0.05的特征
    significant_features_df <- top_features_df[top_features_df$P_value < 0.05, ]
    cat(paste("Found", nrow(significant_features_df), "features with P_value < 0.05\n"))
    
    # 按Importance降序排序
    significant_features_df <- significant_features_df[order(significant_features_df$Importance, decreasing=TRUE), ]
    
    # 保存特征重要性顺序
    feature_importance_order <<- significant_features_df$Feature
    
    # 获取特征ID列表
    top_feature_ids <- significant_features_df$Feature
    cat(paste("Successfully loaded", length(top_feature_ids), "features\n"))
    
    return(top_feature_ids)
  }
}

# 加载样本注释
load_sample_annotations <- function(annotation_file) {
  cat(paste("Reading sample annotation file:", annotation_file, "\n"))
  # 读取注释文件
  annotation_df <- read.delim(annotation_file, stringsAsFactors=FALSE)
  
  # 检查文件是否有足够的列
  if (ncol(annotation_df) < 2) {
    stop("Annotation file must have at least 2 columns: SampleID and at least one annotation column")
  }
  
  # 获取样本ID列（第一列）
  sample_id_col <- colnames(annotation_df)[1]
  # 获取注释列名（除第一列外的所有列）
  annotation_columns <- colnames(annotation_df)[-1]
  
  cat(paste("Loaded annotations for", nrow(annotation_df), "samples with", 
            length(annotation_columns), "annotation types:", 
            paste(annotation_columns, collapse=", "), "\n"))
  
  # 为pheatmap准备annotation_col数据框
  # 确保只包含存在于all_sample_ids中的样本
  valid_samples <- annotation_df[[sample_id_col]] %in% all_sample_ids
  annotation_df <- annotation_df[valid_samples, ]
  
  # 创建行名向量
  sample_ids <- annotation_df[[sample_id_col]]
  
  # 提取注释列
  annotation_col <- as.data.frame(annotation_df[, annotation_columns, drop=FALSE])
  
  # 设置行名
  rownames(annotation_col) <- sample_ids
  
  # 将所有列转换为因子，以确保正确的颜色映射
  for (col in colnames(annotation_col)) {
    annotation_col[[col]] <- as.factor(annotation_col[[col]])
  }
  
  return(list(annotation_col=annotation_col, annotation_columns=annotation_columns))
}

# 加载特征注释
load_feature_annotations <- function(feature_rate_annotation_file) {
  cat(paste("Reading feature rate annotation file:", feature_rate_annotation_file, "\n"))
  # 读取特征注释文件
  feature_annotation_df <- read.delim(feature_rate_annotation_file, stringsAsFactors=FALSE)
  
  # 检查文件是否有足够的列
  if (ncol(feature_annotation_df) < 2) {
    stop("Feature rate annotation file must have at least 2 columns: HOG and Presence_Rate_Interval")
  }
  
  # 获取HOG列（第一列）
  hog_col <- colnames(feature_annotation_df)[1]
  # 获取区间列（第三列）
  interval_col <- colnames(feature_annotation_df)[3]
  
  # 只保留需要的列
  feature_annotation_df <- feature_annotation_df[, c(hog_col, interval_col)]
  
  # 创建HOG到区间的映射
  feature_to_interval <- setNames(feature_annotation_df[[interval_col]], feature_annotation_df[[hog_col]])
  
  # 输出feature_to_interval前几行的内容
  cat("First 5 entries of feature_to_interval:\n")
  for (i in 1:min(5, length(feature_to_interval))) {
    feature_id <- names(feature_to_interval)[i]
    interval_value <- feature_to_interval[[i]]
    cat(paste("  ", i, ": ", feature_id, " -> ", interval_value, "\n"))
  }
  
  cat(paste("Loaded interval information for", length(feature_to_interval), "features\n"))
  
  return(feature_to_interval)
}

# 加载外泌蛋白注释
load_secreted_protein_annotations <- function(file_path) {
  cat(paste("Loading secreted protein annotations from", file_path, "...\n"))
  
  # 读取没有表头的TSV文件（单列或双列）
  annotations <- read.table(file_path, sep="\t", header=FALSE, stringsAsFactors=FALSE)
  
  # 提取特征ID列（第一列）
  secreted_ids <- annotations[, 1]
  cat(paste("Loaded", length(secreted_ids), "secreted protein IDs\n"))
  
  return(secreted_ids)
}

# 加载并过滤特征矩阵
load_and_filter_feature_matrix <- function(feature_matrix_file, all_samples_file, top_feature_ids) {
  cat(paste("Reading feature matrix file:", feature_matrix_file, "\n"))
  # 读取特征矩阵（长格式）
  feature_df <- read.delim(feature_matrix_file, stringsAsFactors=FALSE)
  
  # 检查列数是否符合要求
  if (ncol(feature_df) < 3) {
    stop("Feature matrix file must contain at least 3 columns: Sample ID, Feature ID, Feature Value")
  }
  
  # 读取所有样本ID
  cat(paste("Reading all samples ID file:", all_samples_file, "\n"))
  all_samples_df <- read.delim(all_samples_file, header=FALSE, stringsAsFactors=FALSE)
  all_sample_ids <<- all_samples_df[[1]]
  
  # 过滤特征矩阵以保留在all_samples和top features中的样本
  sample_col <- colnames(feature_df)[1]
  feature_col <- colnames(feature_df)[2]
  value_col <- colnames(feature_df)[3]
  
  filtered_feature_df <- feature_df[feature_df[[sample_col]] %in% all_sample_ids & 
                                    feature_df[[feature_col]] %in% top_feature_ids, ]
  
  # 转换为宽格式（样本×特征）
  filtered_matrix_df <- pivot_wider(filtered_feature_df, 
                                    id_cols = all_of(sample_col),
                                    names_from = all_of(feature_col),
                                    values_from = all_of(value_col))
  
  # 获取样本ID列的值
  sample_ids <- filtered_matrix_df[[sample_col]]
  
  # 移除样本ID列并转换为普通数据框
  filtered_matrix_df <- as.data.frame(filtered_matrix_df)
  filtered_matrix_df <- filtered_matrix_df[, -which(colnames(filtered_matrix_df) == sample_col), drop=FALSE]
  
  # 设置行名为样本ID
  rownames(filtered_matrix_df) <- sample_ids
  
  cat(paste("Feature matrix conversion completed. Number of samples:", 
            nrow(filtered_matrix_df), ", Number of features:", ncol(filtered_matrix_df), "\n"))
  
  # 检查缺失值
  if (sum(is.na(filtered_matrix_df)) > 0) {
    cat(paste("Warning: There are", sum(is.na(filtered_matrix_df)), 
              "missing values in the feature matrix, will fill with median\n"))
    # 用每列的中位数填充缺失值
    filtered_matrix_df <- apply(filtered_matrix_df, 2, function(x) {
      x[is.na(x)] <- median(x, na.rm=TRUE)
      return(x)
    })
    # 确保返回的是数据框而不是矩阵
    if (is.matrix(filtered_matrix_df)) {
      filtered_matrix_df <- as.data.frame(filtered_matrix_df)
    }
  }
  
  # 按照特征重要性顺序对列进行排序
  # 找出存在于filtered_matrix_df和feature_importance_order中共有的列名
  common_features <- intersect(colnames(filtered_matrix_df), feature_importance_order)
  
  # 检查是否有不匹配的情况
  matrix_only_features <- setdiff(colnames(filtered_matrix_df), feature_importance_order)
  order_only_features <- setdiff(feature_importance_order, colnames(filtered_matrix_df))
  
  if (length(order_only_features) > 0) {
    cat(paste("Warning:", length(order_only_features), "features in importance order are not in the matrix and will be ignored.\n"))
  }
  if (length(matrix_only_features) > 0) {
    cat(paste("Warning:", length(matrix_only_features), "features in the matrix are not in the importance order list. These will be placed at the end.\n"))
  }
  
  # 只使用两者共有的feature进行排序
  sorted_cols <- c(
    common_features,
    matrix_only_features
  )
  
  # 重新排序矩阵的列
  filtered_matrix_df <- filtered_matrix_df[, sorted_cols]
  
  # 移除所有值都相同的feature（除非设置了keep_all_features）
  if (!opt$keep_all_features) {
    cat("Checking for features with identical values across all samples...\n")
    initial_feature_count <- ncol(filtered_matrix_df)

    # 检查每一列是否所有值都相同
    identical_features <- sapply(filtered_matrix_df, function(x) length(unique(x)) == 1)

    # 移除值都相同的feature
    if (any(identical_features)) {
      removed_features <- names(filtered_matrix_df)[identical_features]
      filtered_matrix_df <- filtered_matrix_df[, !identical_features, drop = FALSE]

      cat(paste("Removed", sum(identical_features), "features with identical values. \n"))
      cat(paste("Updated number of features:", ncol(filtered_matrix_df), "\n"))
    } else {
      cat("No features with identical values found.\n")
    }
  } else {
    cat("Keeping all features including those with identical values.\n")
  }
  
  return(filtered_matrix_df)
}

# 参考plot_admixture.R的配色方案
# 创建配色方案 - 与plot_admixture.R保持一致的颜色方案
create_group_colors <- function(group_names, col_name = NULL) {
  # 定义各色系颜色列表 - 基于plot_admixture.R的配色风格
  # 高饱和度红色系（用于med）- 使用更鲜艳的红色
  med_red_colors <- c('#FF0000', '#FF3333', '#FF5555', '#FF6666', '#FF4444', '#FF2222')
  # 较低饱和度红色系（用于Human）
  human_red_colors <- c('#E41A1C', '#CC0000', '#B22222', '#A52A2A', '#8B0000', '#CD5C5C')
  # 蓝色系（用于env）
  blue_colors <- c('#1E90FF', '#6495ED', '#87CEEB', '#4682B4', '#5F9EA0', '#708090')
  # 橙色系（用于Mammal）
  orange_colors <- c('#FF8C00', '#FFA726', '#FFB74D', '#FF9800', '#F57C00', '#EF6C00')
  # 土黄色系（用于Soil）
  soil_colors <- c('#DAA520', '#E6BE8A', '#CCA01D', '#CD853F', '#DEB887', '#BC8F8F')
  # 草绿色系（用于Plant）
  plant_colors <- c('#228B22', '#3CB371', '#2E8B57', '#4CAF50', '#66BB6A', '#81C784')
  # 深灰色（用于Unknown）
  unknown_color <- '#555555'

  # npg配色方案（用于Decades列）
  npg_colors <- c("#3B4992", "#EE0000", "#008B45", "#631879", "#008280", "#A20056", "#808080", "#E64B35", "#5BC0DE", "#8B0000")

  # 用于其他标签的备用颜色列表
  other_colors <- c('#377EB8', '#984EA3', '#A65628', '#F781BF',
                    '#999999', '#7570B3', '#E7298A', '#E6AB02', '#1E88E5',
                    '#42A5F5', '#90CAF9', '#1976D2', '#1565C0', '#0D47A1',
                    '#795548', '#A1887F', '#D7CCC8', '#6D4C41', '#5D4037')

  # 创建颜色映射
  color_map <- character(length(group_names))
  names(color_map) <- group_names

  # 判断是否是Decades列
  is_decades_col <- !is.null(col_name) && tolower(col_name) == "decades"

  # 为已知类型的组分配特定色系
  color_index <- 1
  npg_index <- 1

  for (group_name in group_names) {
    # 转为小写进行匹配
    group_lower <- tolower(group_name)

    # Unknown值统一使用深灰色
    if (group_lower == "unknown") {
      color_map[group_name] <- unknown_color
    } else if (is_decades_col) {
      # Decades列使用npg配色方案
      color_map[group_name] <- npg_colors[npg_index %% length(npg_colors) + 1]
      npg_index <- npg_index + 1
    } else if (grepl("med", group_lower)) {
      # med使用高饱和度红色系
      color_map[group_name] <- med_red_colors[color_index %% length(med_red_colors) + 1]
      color_index <- color_index + 1
    } else if (grepl("human", group_lower)) {
      # human使用较低饱和度红色系
      color_map[group_name] <- human_red_colors[color_index %% length(human_red_colors) + 1]
      color_index <- color_index + 1
    } else if (grepl("env", group_lower)) {
      # env使用蓝色系
      color_map[group_name] <- blue_colors[color_index %% length(blue_colors) + 1]
      color_index <- color_index + 1
    } else if (grepl("mammal", group_lower)) {
      # 使用橙色系
      color_map[group_name] <- orange_colors[color_index %% length(orange_colors) + 1]
      color_index <- color_index + 1
    } else if (grepl("soil", group_lower)) {
      # 使用土黄色系
      color_map[group_name] <- soil_colors[color_index %% length(soil_colors) + 1]
      color_index <- color_index + 1
    } else if (grepl("plant", group_lower)) {
      # 使用草绿色系
      color_map[group_name] <- plant_colors[color_index %% length(plant_colors) + 1]
      color_index <- color_index + 1
    } else {
      # 使用备用颜色
      color_map[group_name] <- other_colors[color_index %% length(other_colors) + 1]
      color_index <- color_index + 1
    }
  }

  return(color_map)
}

# 过滤样本的函数（新函数）
filter_samples <- function(matrix_df, sample_annotations) {
  cat("Filtering samples based on annotations...\n")
  
  # 确保输入是矩阵并且有行名
  filtered_matrix <- as.matrix(matrix_df)
  single_species_name <- NULL
  
  # 处理样本注释（行注释）
  if (!is.null(sample_annotations)) {
    # 确保annotation_row与矩阵行名匹配
    annotation_row <- sample_annotations$annotation_col
    common_samples <- intersect(rownames(filtered_matrix), rownames(annotation_row))
    
    if (length(common_samples) > 0) {
      cat(paste("Number of common samples:", length(common_samples), "\n"))
      # 只保留共有样本
      filtered_matrix <- filtered_matrix[common_samples, , drop=FALSE]
      
      # 检查是否只有一个物种，如果是则记录物种名称
      for (col in colnames(annotation_row)) {
        if (tolower(col) == "species" && length(unique(annotation_row[[col]])) == 1) {
          # 记录唯一的物种名称
          single_species_name <- unique(annotation_row[[col]])[1]
          break
        }
      }
    } else {
      cat("Warning: No common samples between data matrix and annotations. No filtering applied.\n")
    }
  }
  
  return(list(
    filtered_matrix = filtered_matrix,
    single_species_name = single_species_name
  ))
}

# 生成样本注释的函数（只生成注释，不修改矩阵）
generate_sample_annotations <- function(matrix_df, sample_annotations) {
  # 初始化返回值
  result <- list(
    annotation_row = NULL,
    annotation_colors = list()
  )

  # 处理样本注释（行注释）
  if (!is.null(sample_annotations)) {
    # 确保annotation_row与矩阵行名匹配
    annotation_row <- sample_annotations$annotation_col
    common_samples <- intersect(rownames(matrix_df), rownames(annotation_row))

    if (length(common_samples) > 0) {
      # 只保留共有样本的注释
      annotation_row <- annotation_row[common_samples, , drop=FALSE]

      # 条件性显示Species注释：如果Species列只有一种值，则移除
      cols_to_keep <- colnames(annotation_row)
      for (col in colnames(annotation_row)) {
        if (tolower(col) == "species" && length(unique(annotation_row[[col]])) == 1) {
          cols_to_keep <- cols_to_keep[cols_to_keep != col]
        }
      }

      # 只保留需要的列
      annotation_row <- annotation_row[, cols_to_keep, drop=FALSE]

      # 处理Species列：只保留样本数量最多的10个物种，其他替换为Others
      if ("Species" %in% colnames(annotation_row)) {
        species_counts <- table(annotation_row[["Species"]])
        species_df <- data.frame(Species = names(species_counts), Count = as.numeric(species_counts), stringsAsFactors = FALSE)
        species_df <- species_df[order(-species_df$Count), ]

        # 分离Unknown和其他
        unknown_species <- species_df[species_df$Species == "Unknown", ]
        non_unknown_species <- species_df[species_df$Species != "Unknown", ]

        # 取前10个（不包括Unknown）
        if (nrow(non_unknown_species) > 10) {
          top_species <- non_unknown_species[1:10, "Species"]
          others_species <- non_unknown_species[11:nrow(non_unknown_species), "Species"]
        } else {
          top_species <- non_unknown_species[, "Species"]
          others_species <- character(0)
        }

        # 替换annotation_row中的Species值
        annotation_row[["Species"]] <- as.character(annotation_row[["Species"]])
        annotation_row[["Species"]][annotation_row[["Species"]] %in% others_species] <- "Others"

        # 转换为因子，重新排序levels（Unknown和Others排在最后）
        all_levels <- c(setdiff(unique(annotation_row[["Species"]]), c("Unknown", "Others")), "Unknown", "Others")
        all_levels <- all_levels[all_levels %in% unique(annotation_row[["Species"]])]
        annotation_row[["Species"]] <- factor(annotation_row[["Species"]], levels = all_levels)

        cat(paste("Species annotation processed:", length(top_species), "top species kept,", length(others_species), "grouped as Others\n"))
      }

      # 处理所有列的Unknown值：确保Unknown排在最后
      for (col in colnames(annotation_row)) {
        col_levels <- levels(annotation_row[[col]])
        if (!is.null(col_levels) && "Unknown" %in% col_levels) {
          # 将Unknown移到levels的最后
          col_levels <- c(setdiff(col_levels, "Unknown"), "Unknown")
          annotation_row[[col]] <- factor(annotation_row[[col]], levels = col_levels)
        }
      }

      # 如果还有注释列，则添加到结果中
      if (ncol(annotation_row) > 0) {
        result$annotation_row <- annotation_row

        # 为每个注释列创建配色方案
        for (col in colnames(annotation_row)) {
          group_names <- levels(annotation_row[[col]])
          if (length(group_names) == 0) {
            group_names <- unique(annotation_row[[col]])
          }
          result$annotation_colors[[col]] <- create_group_colors(group_names, col_name = col)
        }
      }
    }
  }

  return(result)
}

# 生成特征注释的函数（只生成注释，不修改矩阵）
generate_feature_annotations <- function(matrix_df, feature_to_interval=NULL, feature_secreted_annotation=NULL, enable_col_annotation=TRUE) {
  
  # 初始化返回值
  result <- list(
    annotation_col = NULL,
    annotation_colors = list()
  )
  
  # 如果列注释被禁用，直接返回空结果
  if (!enable_col_annotation) {
    cat("Col annotation is disabled, skipping feature annotations\n")
    return(result)
  }
  
  # 获取矩阵中的特征名称
  feature_names <- colnames(matrix_df)
  
  # 添加特征注释（列注释）
  annotation_col <- NULL
  annotation_colors <- list()
  
  # 处理外泌蛋白注释
  if (!is.null(feature_secreted_annotation)) {
    # 1. 创建一个包含所有矩阵特征的完整数据框
    # 使用字符型而不是因子型避免因子级别问题
    all_features <- feature_names
    
    # 2. 创建注释数据框，初始值设为"No"
    secreted_annotations <- data.frame(
      Secreted = rep("No", length(all_features)),
      row.names = all_features,
      stringsAsFactors = FALSE
    )
    
    # 3. 为在feature_secreted_annotation中存在的特征设置为"Yes"
    if (!is.null(feature_secreted_annotation) && length(feature_secreted_annotation) > 0) {
      # 找出在feature_secreted_annotation中存在的特征
      common_features <- intersect(all_features, feature_secreted_annotation)
      secreted_count <- length(common_features)
      
      if (secreted_count > 0) {
        secreted_annotations[common_features, "Secreted"] <- "Yes"
      }
    }
    
    # 为列设置友好显示名称
    colnames(secreted_annotations) <- "Secreted Protein"
    
    # 创建紫色的颜色映射
    annotation_colors[[colnames(secreted_annotations)[1]]] <- c("Yes" = "#9933CC", "No" = "#FFFFFF")
    
    # 设置列注释
    annotation_col <- secreted_annotations
  }
  
  # 处理特征区间注释
  if (!is.null(feature_to_interval)) {
    # 采用新逻辑：先合并，再过滤，最后确保与矩阵特征匹配
    # 1. 确保feature_to_interval是一个命名列表或向量
    if (is.null(names(feature_to_interval))) {
      # 静默跳过无名称的区间注释
    } else {
      # 2. 准备所有需要的特征
      all_features <- feature_names
      
      # 3. 创建包含所有矩阵特征的数据框，初始值设为"Unknown"，使用字符型
      interval_annotations <- data.frame(
        presence_rate = rep("Unknown", length(all_features)),
        row.names = all_features,
        stringsAsFactors = FALSE  # 使用字符型避免因子级别问题
      )
      
      # 4. 找出在feature_to_interval中存在的特征
      common_features <- intersect(all_features, names(feature_to_interval))
      
      # 5. 只为有区间信息的特征填充值
      if (length(common_features) > 0) {
        interval_annotations[common_features, 1] <- as.character(feature_to_interval[common_features])
      }
      
      # 为列设置友好显示名称
      colnames(interval_annotations) <- "Presence Rate"
      
      # 先收集所有可能的区间值
      all_possible_levels <- unique(interval_annotations[, 1])
      
      # 为Presence Rate区间创建数值排序
      # 尝试按区间范围的数值顺序排序
      # 定义一个函数来提取区间的起始数值用于排序
      extract_start_value <- function(interval_str) {
        # 提取数字部分（假设格式类似"0-20%", "20-40%"等）
        if (grepl("^[0-9]+", interval_str)) {
          # 提取以数字开头的部分
          start_num <- as.numeric(sub("^([0-9]+).*", "\\1", interval_str))
          return(start_num)
        } else if (interval_str == "Unknown") {
          # 未知类型放在最后
          return(999)
        } else {
          # 其他情况使用字母顺序
          return(500)  # 中间值，避免影响正常区间排序
        }
      }
      
      # 对区间级别进行排序
      sorted_levels <- all_possible_levels[order(sapply(all_possible_levels, extract_start_value))]
      
      # 将区间信息转换为因子类型，使用排序后的级别
      interval_annotations[, 1] <- factor(interval_annotations[, 1], levels = sorted_levels)
      
      # 显示区间水平
      interval_levels <- levels(interval_annotations[, 1])
      
      # 使用Spectral色系创建颜色映射
      n_levels <- length(interval_levels)
      if (n_levels > 0) {
        # 确保至少有3个颜色级别
        if (n_levels < 3) {
          # 如果级别少于3个，创建一个自定义的颜色映射
          if (n_levels == 1) {
            # 只有一个级别，使用单一颜色
            spectral_colors <- c("#8DD3C7")
          } else if (n_levels == 2) {
            # 两个级别，使用对比色
            spectral_colors <- c("#8DD3C7", "#BEBADA")
          }
        } else {
          # 使用Spectral颜色
          spectral_colors <- colorRampPalette(rev(brewer.pal(n=min(11, n_levels), name="Spectral")))(n_levels)
        }
        
        # 创建颜色映射
        annotation_colors[[colnames(interval_annotations)[1]]] <- setNames(spectral_colors, interval_levels)
      }
      
      # 如果已经有外泌蛋白注释，则合并两个注释数据框
      if (!is.null(annotation_col)) {
        # 确保两个数据框具有相同的行名和长度
        if (identical(rownames(annotation_col), rownames(interval_annotations))) {
          annotation_col <- cbind(annotation_col, interval_annotations)
        } else {
          # 保留外泌蛋白注释
        }
      } else {
        # 如果没有外泌蛋白注释，则直接使用区间注释
        annotation_col <- interval_annotations
      }
    }
  }
  
  # 最终验证：确保注释数据框的行名与矩阵特征完全匹配，并且不包含NA值
  if (!is.null(annotation_col)) {
    # 找出实际需要的特征（矩阵中的特征）
    final_features <- feature_names
    
    # 确保注释数据框包含所有必要的特征
    if (any(!final_features %in% rownames(annotation_col))) {
      # 创建一个新的数据框，只包含矩阵中的特征
      missing_features <- final_features[!final_features %in% rownames(annotation_col)]
      
      # 重新创建注释数据框，确保包含所有矩阵特征
      new_annotation_col <- annotation_col[intersect(rownames(annotation_col), final_features), , drop = FALSE]
      
      # 为缺失的特征创建空行（使用注释中已有的列和默认值）
      if (length(missing_features) > 0) {
        # 获取现有的列名
        existing_cols <- colnames(new_annotation_col)
        
        # 创建缺失特征的数据框，使用适当的默认值
        missing_df <- data.frame(
          matrix(nrow = length(missing_features), 
                 ncol = length(existing_cols), 
                 dimnames = list(missing_features, existing_cols),
                 stringsAsFactors = FALSE)  # 使用字符型避免因子级别问题
        )
        
        # 为每列设置适当的默认值
        for (col in existing_cols) {
          # 根据列名和类型设置默认值
          if (grepl("Secreted", col)) {
            missing_df[[col]] <- "No"
          } else if (grepl("Rate", col)) {
            missing_df[[col]] <- "Unknown"
          } else {
            missing_df[[col]] <- "Unknown"
          }
        }
        
        # 合并现有注释和缺失特征的注释
        new_annotation_col <- rbind(new_annotation_col, missing_df)
        
        # 确保行名顺序与矩阵特征一致
        new_annotation_col <- new_annotation_col[final_features, , drop = FALSE]
      }
      
      # 更新为新的数据框
      annotation_col <- new_annotation_col
    }
    
    # 最后确认行名与矩阵特征完全匹配
    if (!identical(rownames(annotation_col), final_features)) {
      # 强制使用矩阵特征名作为行名
      rownames(annotation_col) <- final_features
    }
    
    # 处理NA值（静默模式）
    if (any(is.na(annotation_col))) {
      # 替换NA值 - 静默模式，不显示警告
      suppressWarnings({
        for (col in colnames(annotation_col)) {
          na_positions <- is.na(annotation_col[[col]])
          if (any(na_positions)) {
            if (grepl("Secreted", col)) {
              annotation_col[[col]][na_positions] <- "No"
            } else if (grepl("Rate", col)) {
              annotation_col[[col]][na_positions] <- "Unknown"
            } else {
              annotation_col[[col]][na_positions] <- "Unknown"
            }
          }
        }
      })
    }
    
    # 确保所有列都是因子类型，并且因子级别包含所有可能的值
    for (col in colnames(annotation_col)) {
      if (!is.factor(annotation_col[[col]])) {
        # 收集所有唯一值作为因子级别
        all_levels <- unique(annotation_col[[col]])
        # 转换为因子
        annotation_col[[col]] <- factor(annotation_col[[col]], levels = all_levels)
      }
    }
  }
  
  result$annotation_col <- annotation_col
  result$annotation_colors <- annotation_colors
  
  return(result)
}

# 绘制聚类热图
plot_heatmap_with_clustering <- function(scaled_data, output_prefix, figsize, cmap,
                                        annotation_row=NULL, annotation_col=NULL, annotation_colors=NULL,
                                        single_species_name=NULL, cellwidth=6, cellheight=6) {
  cat("Starting to plot heatmap with clustering analysis...\n")

  # 字体大小设置为6，比原来的7小1号
  fontsize_val <- 7
  
  # 计算特征间的距离矩阵（欧氏距离）
  feature_dist <- dist(t(scaled_data), method = "euclidean")
  
  # 执行ward.D2聚类
  feature_hclust <- hclust(feature_dist, method = "ward.D2")

  # 获取特征数量
  num_features <- ncol(scaled_data)
  
  # 设置pheatmap参数
  pheatmap_params <- list(
    mat = scaled_data,
    scale = "none",  # 标准化已在上方手动处理或跳过
    clustering_method = "ward.D2",
    cluster_rows = TRUE,  # 样本行仍进行聚类
    cluster_cols = TRUE,  # 特征列进行聚类
    treeheight_row = 20,
    treeheight_col = 20,
    fontsize_row = fontsize_val,
    fontsize_col = fontsize_val,
    show_rownames = TRUE,
    show_colnames = FALSE,
    cellheight = cellheight,
    border_color = "lightgray",
    main = ifelse(max(scaled_data, na.rm = TRUE) == 1, "PAV of Significant Features (P-value < 0.05)", "Normalized Count of Significant Features (P_value < 0.05)")
  )

  # 根据特征数量决定是否设置固定的cellwidth
  if (num_features <= 200) {
    # 特征数量不超过200，设置固定的cellwidth
    pheatmap_params$cellwidth <- cellwidth
    pheatmap_params$show_colnames = TRUE
    cat(paste("Setting cellwidth=", cellwidth, "for", num_features, "features\n"))
  } else {
    # 特征数量超过200，不设置固定的cellwidth，由pheatmap自动调整
    cat(paste("Features count (", num_features, ") exceeds 200, cellwidth will be automatically adjusted\n", sep=""))
  }

  # 获取样本数量
  num_samples <- nrow(scaled_data)

  # 根据样本数量决定是否设置固定的cellheight和显示样本名称
  if (num_samples > 100) {
    # 样本数量超过100，不设置固定的cellheight，由pheatmap自动调整
    pheatmap_params$cellheight <- NA
    pheatmap_params$show_rownames <- FALSE
    cat(paste("Sample count (", num_samples, ") exceeds 100, cellheight will be auto-adjusted and sample names will be hidden\n", sep=""))
  } else {
    # 样本数量不超过100，使用自定义的cellheight
    cat(paste("Using cellheight=", cellheight, "for", num_samples, "samples\n"))
  }
  
  # 根据数据类型设置不同的颜色方案
  if (max(scaled_data, na.rm = TRUE) == 1) {
    # Onehot数据：使用viridis配色方案的两端颜色
    cat("Using viridis color scheme endpoints for onehot data.\n")
    pheatmap_params$color <- c("#440154", "#FDE725")  # viridis配色方案的两端颜色
  } else {
    # Count数据：使用Spectral配色方案
    cat("Using Spectral colorkey for count data.\n")
    pheatmap_params$color <- colorRampPalette(rev(brewer.pal(n=11, name="Spectral")))(100)
  }
  
  # 根据是否只有一个物种来修改标题
  if (!is.null(single_species_name)) {
    # 如果只有一个物种，在标题中添加物种名称
    if (max(scaled_data, na.rm = TRUE) == 1) {
      pheatmap_params$main <- paste("PAV of Significant Features (P-value < 0.05) -", single_species_name)
    } else {
      pheatmap_params$main <- paste("Normalized Count of Significant Features (P_value < 0.05) -", single_species_name)
    }
  }
  
  # 添加行注释（如果有）
  if (!is.null(annotation_row)) {
    pheatmap_params$annotation_row <- annotation_row
  }
  
  # 添加列注释（如果有）
  if (!is.null(annotation_col)) {
    # 确保注释数据框中没有NA值
    if (any(is.na(annotation_col))) {
      cat("Warning: NA values in annotation_col, removing annotation_col to avoid pheatmap errors\n")
      annotation_col <- NULL
    } else {
      pheatmap_params$annotation_col <- annotation_col
    }
  }
  
  # 添加注释颜色（如果有）
  if (!is.null(annotation_colors) && length(annotation_colors) > 0) {
    pheatmap_params$annotation_colors <- annotation_colors
  }
  
  # 设置PNG输出文件
  png_output_file <- paste0(output_prefix, ".png")
  
  # 设置图形尺寸并保存为PNG
  png(png_output_file, width=figsize[1], height=figsize[2], units="in", res=300)
  
  # 静默模式：移除完整表格内容调试输出
  
  # 静默模式：移除颜色映射调试输出
  
  # 绘制热图
  pheatmap_obj <- do.call(pheatmap, pheatmap_params)

  # 调整布局并保存图形
  dev.off()

  cat(paste("Heatmap saved to:", png_output_file, "\n"))
  
  # 设置PDF输出文件
  pdf_output_file <- paste0(output_prefix, ".pdf")
  
  # 保存为PDF格式
  pdf(pdf_output_file, width=figsize[1], height=figsize[2])
  
  # 绘制热图
  pheatmap_obj <- do.call(pheatmap, pheatmap_params)
  
  # 关闭PDF设备
  dev.off()
  
  cat(paste("Heatmap saved to:", pdf_output_file, "\n"))
}

# 主函数
main <- function() {
  tryCatch({
    # 1. 加载top特征ID
    top_feature_ids <- load_top_features(opt$top_features_file)
    
    # 2. 加载特征矩阵（不进行ID转换）
    filtered_matrix_df <- load_and_filter_feature_matrix(
      opt$feature_matrix, 
      opt$all_samples, 
      top_feature_ids
    )
    
    # 检查加载的特征矩阵是否有NA值
    if (any(is.na(filtered_matrix_df))) {
      na_count <- sum(is.na(filtered_matrix_df))
      cat(sprintf("[DEBUG] After loading feature matrix: %d NA values found in filtered_matrix_df\n", na_count))
    } else {
      cat("[DEBUG] After loading feature matrix: No NA values in filtered_matrix_df\n")
    }
    
    # 3. 加载样本注释（如果提供）
    sample_annotations <- NULL
    if (!is.null(opt$annotation_file)) {
      sample_annotations <- load_sample_annotations(opt$annotation_file)
    }
    
    # 4. 加载特征注释（如果提供）
    feature_to_interval <- NULL
    enable_col_annotation <- FALSE
    if (!is.null(opt$feature_rate_annotation_file)) {
      feature_to_interval <- load_feature_annotations(opt$feature_rate_annotation_file)
      enable_col_annotation <- TRUE
    }
    
    # 5. 加载外泌蛋白注释（如果提供）
    feature_secreted_annotation <- NULL
    if (!is.null(opt$feature_secreted_annotation_file)) {
      feature_secreted_annotation <- load_secreted_protein_annotations(opt$feature_secreted_annotation_file)
    }
    
    # 6. 执行数据标准化（在注释生成前进行）
    cat("\nPerforming data normalization...\n")
    
    # 再次检查filtered_matrix_df是否有NA值（加载后到标准化前）
    if (any(is.na(filtered_matrix_df))) {
      na_count <- sum(is.na(filtered_matrix_df))
      cat(sprintf("[DEBUG] Before normalization: %d NA values found in filtered_matrix_df\n", na_count))
    } else {
      cat("[DEBUG] Before normalization: No NA values in filtered_matrix_df\n")
    }
    
    # 检查矩阵中的最大值，判断是否为onehot数据
    max_value <- max(as.matrix(filtered_matrix_df), na.rm = TRUE)
    cat(paste("Matrix maximum value:", max_value, "\n"))

    # 根据最大值和skip_normalization标志判断是否需要标准化
    if (max_value == 1) {
      cat("Detected onehot-like data (max value = 1), skipping normalization.\n")
      # 直接使用原始数据，不进行标准化
      normalized_matrix <- as.matrix(filtered_matrix_df)
    } else if (opt$skip_normalization) {
      cat("Skipping normalization as requested (plotting raw count data).\n")
      normalized_matrix <- as.matrix(filtered_matrix_df)
    } else {
      cat("Performing data normalization.\n")
      # 修改为按列（特征）标准化数据
      normalized_matrix <- apply(filtered_matrix_df, 2, function(x) (x - mean(x)) / sd(x))
      # 将标准化后的值限制在合理范围内，避免极端值
      normalized_matrix[normalized_matrix < -3] <- -3
      normalized_matrix[normalized_matrix > 3] <- 3
    }
    
    # 确保是矩阵并且有行名
    if (!is.matrix(normalized_matrix)) {
      normalized_matrix <- as.matrix(normalized_matrix)
    }
    
    # 检查标准化后是否有NA值
    if (any(is.na(normalized_matrix))) {
      na_count <- sum(is.na(normalized_matrix))
      cat(sprintf("[DEBUG] After normalization: %d NA values found in matrix\n", na_count))
    } else {
      cat("[DEBUG] After normalization: No NA values in matrix\n")
    }
    
    # 8. 过滤样本（新增步骤）
    filter_result <- filter_samples(normalized_matrix, sample_annotations)
    normalized_matrix <- filter_result$filtered_matrix
    single_species_name <- filter_result$single_species_name
    
    # 检查过滤样本后是否有NA值
    if (any(is.na(normalized_matrix))) {
      na_count <- sum(is.na(normalized_matrix))
      cat(sprintf("[DEBUG] After sample filtering: %d NA values found in matrix\n", na_count))
    } else {
      cat("[DEBUG] After sample filtering: No NA values in matrix\n")
    }
    
    # 9. 生成样本注释（行注释）
    sample_annot_result <- generate_sample_annotations(normalized_matrix, sample_annotations)
    
    # 10. 生成特征注释（列注释）
    feature_annot_result <- generate_feature_annotations(normalized_matrix, feature_to_interval, feature_secreted_annotation, enable_col_annotation)
    
    # 检查生成注释后是否有NA值
    if (any(is.na(normalized_matrix))) {
      na_count <- sum(is.na(normalized_matrix))
      cat(sprintf("[DEBUG] After annotations: %d NA values found in matrix\n", na_count))
    } else {
      cat("[DEBUG] After annotations: No NA values in matrix\n")
    }
    
    # 合并颜色映射
    merged_annotation_colors <- c(sample_annot_result$annotation_colors, feature_annot_result$annotation_colors)
    
    # 11. 绘制聚类热图
    plot_heatmap_with_clustering(
      normalized_matrix,
      opt$output_prefix,
      figsize=c(opt$figsize_width, opt$figsize_height),
      cmap=opt$cmap,
      annotation_row=sample_annot_result$annotation_row,
      annotation_col=feature_annot_result$annotation_col,
      annotation_colors=merged_annotation_colors,
      single_species_name=single_species_name,
      cellwidth=opt$cellwidth,
      cellheight=opt$cellheight
    )
    
    cat("\nAnalysis completed!\n")
    cat(paste("Heatmap saved to:", paste0(opt$output_prefix, ".png"), "and", paste0(opt$output_prefix, ".pdf"), "\n"))
    cat(paste("Number of features used:", length(top_feature_ids), "\n"))
    cat(paste("Number of samples used:", nrow(filtered_matrix_df), "\n"))
    if (!is.null(sample_annotations)) {
      cat(paste("Number of sample annotation types:", 
                length(sample_annotations$annotation_columns), "\n"))
      cat(paste("Annotation type names from file header:", 
                paste(sample_annotations$annotation_columns, collapse=", "), "\n"))
    }
    if (!is.null(feature_to_interval)) {
      cat(paste("Feature presence rate intervals loaded for", length(feature_to_interval), "features\n"))
    }
    if (!is.null(feature_secreted_annotation)) {
      cat(paste("Secreted protein annotations loaded for", length(feature_secreted_annotation), "features\n"))
    }
  }, error = function(e) {
    cat(paste("Error during analysis:", e$message, "\n"))
    traceback()
    quit(status=1)
  })
}

# 运行主函数
main()